package pattern;

public class Neewww {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int i=1;i<=5;i++)
		{
			for(int k=5;k>=1;k--)
			{
				System.out.println(" ");
			}
			for(int j=1;j<=5;j++)
			{
				System.out.println("*");
			}
			
				
			
		}

	}

}
